from math import comb
from typing import Sequence

def overlap(r: int, a: Sequence[int], b: Sequence[int]) -> int:
    return comb(len(set(a) & set(b)), r)

a = (0, 1, 2, 3, 4)
for b in [(0,1,2,5,6), (0,1,5,6,7), (5,6,7,8,9)]:
    print(a, b, overlap(3, a, b))

